/**
 ******************************************************************************
 * @file    tony_ports.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) in the PD6 RTOS port (Sep 2026) for Tony's display task.
 * @brief   SPI1 (TFT) and ADC1 (touch) wrappers for TonyTask.
 *
 * Owner: Tony Le — Touchscreen UI (PD6).
 *
 * RTOS role: helpers for TonyTask only (owner-task pattern, slide 22).
 * Before the kernel runs (ILI9341_Init from Tony_Init) the blocking path is
 * used unconditionally.
 *
 * No task of its own: every SPI transmit of the ILI9341 driver and every
 * touch ADC read of tony_ui.c ends up here, inside TonyTask, or in
 * Tony_Init before the kernel starts (slide 22 = ZEIT4230 lecture 07:
 * only the owner task touches its peripheral). Each call takes one of two
 * paths (tony_ports.h): the interrupt path, where the task sleeps on a
 * thread flag until the "done" interrupt sets it, or the blocking HAL
 * call. This .ioc enables neither interrupt, so today every call blocks:
 * the CPU waits until the transfer or conversion is done.
 ******************************************************************************/
#include "tony_ports.h"
#include "app_rtos.h"

#define SPI_TIMEOUT_MS   50U   /* the longest transmit, one 500 B burst (BURST_MAX_SIZE) at 9 MHz, is ~0.5 ms */
#define ADC_TIMEOUT_MS   10U

static SPI_HandleTypeDef *s_hspi = NULL;
static ADC_HandleTypeDef *s_hadc = NULL;

void TonyPorts_Init(SPI_HandleTypeDef *hspi, ADC_HandleTypeDef *hadc)
{
    s_hspi = hspi;
    s_hadc = hadc;
}

/* The interrupt path waits on one of TonyTask's thread flags, so it may only
 * run inside TonyTask once the kernel is running. Before that (Tony_Init
 * draws the boot splash) there is no task to wake: the blocking path. */
static uint8_t in_tony_task(void)
{
    return (osKernelGetState() == osKernelRunning && osThreadGetId() == TonyTaskHandle) ? 1U : 0U;
}

/* 1 if CubeMX has enabled the matching interrupt, so the interrupt path can
 * be used (checked at run time, NVIC_GetEnableIRQ). */
static uint8_t spi_is_interrupt_driven(void) { return NVIC_GetEnableIRQ(SPI1_IRQn) ? 1U : 0U; }
static uint8_t adc_is_interrupt_driven(void) { return NVIC_GetEnableIRQ(ADC_IRQn)  ? 1U : 0U; }

/* ------------------------------- SPI1 ----------------------------------- */
void TonyPorts_SpiTransmit(const uint8_t *data, uint16_t len)
{
    if (s_hspi == NULL || data == NULL || len == 0U) return;

    if (in_tony_task() && spi_is_interrupt_driven()) {
        (void)osThreadFlagsClear(TONY_SPI_DONE_FLAG);
        if (HAL_SPI_Transmit_IT(s_hspi, (uint8_t *)data, len) == HAL_OK) {
            uint32_t f = osThreadFlagsWait(TONY_SPI_DONE_FLAG, osFlagsWaitAny, SPI_TIMEOUT_MS);
            if ((f & osFlagsError) != 0U) {
                (void)HAL_SPI_Abort_IT(s_hspi);      /* timeout: recover, the draw is lost */
            }
            return;
        }
    }
    /* Blocking fallback — sole owner, listed in the blocking-call audit.
     * TODO(TONY): enable the SPI1 global interrupt in CubeMX (priority >= 5)
     * and this branch is never taken. */
    (void)HAL_SPI_Transmit(s_hspi, (uint8_t *)data, len, SPI_TIMEOUT_MS);
}

void TonyPorts_SpiDoneISR(void)
{
    if (TonyTaskHandle != NULL) (void)osThreadFlagsSet(TonyTaskHandle, TONY_SPI_DONE_FLAG);
}

/* ------------------------------- ADC1 ----------------------------------- */
uint16_t TonyPorts_AdcRead(uint32_t channel)
{
    if (s_hadc == NULL) return 0U;

    ADC_ChannelConfTypeDef sConfig = {0};
    sConfig.Channel = channel;
    sConfig.Rank = 1;
    sConfig.SamplingTime = ADC_SAMPLETIME_144CYCLES;
    if (HAL_ADC_ConfigChannel(s_hadc, &sConfig) != HAL_OK) return 0U;

    if (in_tony_task() && adc_is_interrupt_driven()) {
        (void)osThreadFlagsClear(TONY_ADC_DONE_FLAG);
        if (HAL_ADC_Start_IT(s_hadc) == HAL_OK) {
            uint32_t f = osThreadFlagsWait(TONY_ADC_DONE_FLAG, osFlagsWaitAny, ADC_TIMEOUT_MS);
            uint16_t v = ((f & osFlagsError) == 0U) ? (uint16_t)HAL_ADC_GetValue(s_hadc) : 0U;
            (void)HAL_ADC_Stop_IT(s_hadc);
            return v;
        }
    }
    /* Blocking fallback (~10 us actual wait at 144 cycles) — sole owner.
     * TODO(TONY): enable the ADC global interrupt in CubeMX (priority >= 5). */
    (void)HAL_ADC_Start(s_hadc);
    if (HAL_ADC_PollForConversion(s_hadc, ADC_TIMEOUT_MS) != HAL_OK) {
        (void)HAL_ADC_Stop(s_hadc);
        return 0U;
    }
    uint16_t value = (uint16_t)HAL_ADC_GetValue(s_hadc);
    (void)HAL_ADC_Stop(s_hadc);
    return value;
}

void TonyPorts_AdcDoneISR(void)
{
    if (TonyTaskHandle != NULL) (void)osThreadFlagsSet(TonyTaskHandle, TONY_ADC_DONE_FLAG);
}
